5-agent/agent框架/pi-agent/pi-sdk-demo/10-.content:
10 - 设置配置
使用 SettingsManager 覆盖设置。
import { createAgentSession, SessionManager, SettingsManager } from &quot;@earendil-works/pi-coding-agent&quot;;

const cwd = process.cwd();

// 加载当前设置（合并全局 + 项目设置）
const settingsManagerFromDisk = SettingsManager.create(cwd);
console.log(&quot;Current settings:&quot;, JSON.stringify(settingsManagerFromDisk.getGlobalSettings(), null, 2));

// 覆盖特定设置
const settingsManager = SettingsManager.create(cwd);
settingsManager.applyOverrides({
	compaction: { enabled: false },
	retry: { enabled: true, maxRetries: 5, baseDelayMs: 1000 },
});

const { session: customSettingsSession } = await createAgentSession({
	settingsManager,
	sessionManager: SessionManager.inMemory(),
});
console.log(&quot;Session created with custom settings&quot;);
customSettingsSession.dispose();

// Setter 会立即更新内存并排队持久化写入。
// 在需要持久化边界时调用 flush()。
settingsManager.setDefaultThinkingLevel(&quot;low&quot;);
await settingsManager.flush();

// 在应用层显示设置 I/O 错误。
const settingsErrors = settingsManager.drainErrors();
if (settingsErrors.length &gt; 0) {
	for (const { scope, error } of settingsErrors) {
		console.warn(`Warning (${scope} settings): ${error.message}`);
	}
}

// 无文件 I/O 的测试用内存设置：
const inMemorySettings = SettingsManager.inMemory({
	compaction: { enabled: false },
	retry: { enabled: false },
});

const { session: testSession } = await createAgentSession({
	settingsManager: inMemorySettings,
	sessionManager: SessionManager.inMemory(),
});
console.log(&quot;Test session created with in-memory settings&quot;);
testSession.dispose();

5-agent/agent框架/pi-agent/pi-sdk-demo/11-.content:
11 - 会话管理
控制会话持久化：内存会话、新建文件会话、继续会话或打开指定会话。
import { createAgentSession, SessionManager } from &quot;@earendil-works/pi-coding-agent&quot;;

// 内存会话（无持久化）
const { session: inMemory } = await createAgentSession({
	sessionManager: SessionManager.inMemory(),
});
console.log(&quot;In-memory session:&quot;, inMemory.sessionFile ?? &quot;(none)&quot;);
inMemory.dispose();

// 新建持久化会话
const { session: newSession } = await createAgentSession({
	sessionManager: SessionManager.create(process.cwd()),
});
console.log(&quot;New session file:&quot;, newSession.sessionFile);
newSession.dispose();

// 继续最近的会话（如果没有则新建）
const { session: continued, modelFallbackMessage } = await createAgentSession({
	sessionManager: SessionManager.continueRecent(process.cwd()),
});
if (modelFallbackMessage) console.log(&quot;Note:&quot;, modelFallbackMessage);
console.log(&quot;Continued session:&quot;, continued.sessionFile);
continued.dispose();

// 列出并打开指定会话
const sessions = await SessionManager.list(process.cwd());
console.log(`\nFound ${sessions.length} sessions:`);
for (const info of sessions.slice(0, 3)) {
	console.log(`  ${info.id.slice(0, 8)}... - &quot;${info.firstMessage.slice(0, 30)}...&quot;`);
}

if (sessions.length &gt; 0) {
	const { session: opened } = await createAgentSession({
		sessionManager: SessionManager.open(sessions[0].path),
	});
	console.log(`\nOpened: ${opened.sessionId}`);
	opened.dispose();
}

