5-agent/agent框架/pi-agent/pi-sdk-demo/12-.content:
12 - 完全控制
替换所有内容 —— 不进行自动发现，完全显式配置。
import { getModel } from &quot;@earendil-works/pi-ai/compat&quot;;
import {
	createAgentSession,
	createExtensionRuntime,
	ModelRuntime,
	type ResourceLoader,
	SessionManager,
	SettingsManager,
} from &quot;@earendil-works/pi-coding-agent&quot;;

const modelRuntime = await ModelRuntime.create({
	authPath: &quot;/tmp/my-agent/auth.json&quot;,
	modelsPath: &quot;/tmp/my-agent/models.json&quot;,
});
if (process.env.MY_ANTHROPIC_KEY) {
	await modelRuntime.setRuntimeApiKey(&quot;anthropic&quot;, process.env.MY_ANTHROPIC_KEY);
}

const model = getModel(&quot;anthropic&quot;, &quot;claude-sonnet-4-5&quot;);
if (!model) throw new Error(&quot;Model not found&quot;);

// 带覆盖的内存设置
const settingsManager = SettingsManager.inMemory({
	compaction: { enabled: false },
	retry: { enabled: true, maxRetries: 2 },
});

const cwd = process.cwd();

const resourceLoader: ResourceLoader = {
	getExtensions: () =&gt; ({ extensions: [], errors: [], runtime: createExtensionRuntime() }),
	getSkills: () =&gt; ({ skills: [], diagnostics: [] }),
	getPrompts: () =&gt; ({ prompts: [], diagnostics: [] }),
	getThemes: () =&gt; ({ themes: [], diagnostics: [] }),
	getAgentsFiles: () =&gt; ({ agentsFiles: [] }),
	getSystemPrompt: () =&gt; `You are a minimal assistant.
Available: read, bash. Be concise.`,
	getSystemPromptSource: () =&gt; undefined,
	getAppendSystemPrompt: () =&gt; [],
	getAppendSystemPromptSources: () =&gt; [],
	extendResources: () =&gt; {},
	reload: async () =&gt; {},
};

const { session } = await createAgentSession({
	cwd,
	agentDir: &quot;/tmp/my-agent&quot;,
	model,
	thinkingLevel: &quot;off&quot;,
	modelRuntime,
	resourceLoader,
	tools: [&quot;read&quot;, &quot;bash&quot;],
	sessionManager: SessionManager.inMemory(cwd),
	settingsManager,
});

try {
	session.subscribe((event) =&gt; {
		if (event.type === &quot;message_update&quot; &amp;&amp; event.assistantMessageEvent.type === &quot;text_delta&quot;) {
			process.stdout.write(event.assistantMessageEvent.delta);
		}
	});

	await session.prompt(&quot;List files in the current directory.&quot;);
	console.log();
} finally {
	session.dispose();
}

5-agent/agent框架/pi-agent/pi-sdk-demo/13-.content:
13 - 会话运行时
当你需要替换活跃的 AgentSession 时使用 AgentSessionRuntime，例如用于新建会话、恢复、分叉或导入流程。
重要的模式是：运行时替换活跃会话后，需要将所有会话级别的订阅和扩展绑定重新绑定到 runtime.session。
import {
	type CreateAgentSessionRuntimeFactory,
	createAgentSessionFromServices,
	createAgentSessionRuntime,
	createAgentSessionServices,
	getAgentDir,
	SessionManager,
} from &quot;@earendil-works/pi-coding-agent&quot;;

const createRuntime: CreateAgentSessionRuntimeFactory = async ({ cwd, sessionManager, sessionStartEvent }) =&gt; {
	const services = await createAgentSessionServices({ cwd });
	return {
		...(await createAgentSessionFromServices({
			services,
			sessionManager,
			sessionStartEvent,
		})),
		services,
		diagnostics: services.diagnostics,
	};
};
const runtime = await createAgentSessionRuntime(createRuntime, {
	cwd: process.cwd(),
	agentDir: getAgentDir(),
	sessionManager: SessionManager.create(process.cwd()),
});

let unsubscribe: (() =&gt; void) | undefined;

async function bindSession() {
	unsubscribe?.();
	const session = runtime.session;
	await session.bindExtensions({});
	unsubscribe = session.subscribe((event) =&gt; {
		if (event.type === &quot;queue_update&quot;) {
			console.log(&quot;Queued:&quot;, event.steering.length + event.followUp.length);
		}
	});
	return session;
}

let session = await bindSession();
const originalSessionFile = session.sessionFile;
console.log(&quot;Initial session:&quot;, originalSessionFile);

// 新建会话
await runtime.newSession();
session = await bindSession();
console.log(&quot;After newSession():&quot;, session.sessionFile);

// 切换回原会话
if (originalSessionFile) {
	await runtime.switchSession(originalSessionFile);
	session = await bindSession();
	console.log(&quot;After switchSession():&quot;, session.sessionFile);
}

unsubscribe?.();
await runtime.dispose();

